-- V7: Seed explanation (giai thich chi tiet) cho 600 cau hoi
-- Nguon: soan tu cau hoi + dap an dung (Cuc CSGT - Bo Cong an 2025)

BEGIN;

UPDATE questions SET explanation = 'Theo Luật Giao thông đường bộ, phần đường xe chạy là phần của đường bộ được sử dụng cho phương tiện giao thông đường bộ đi lại. Phương án A nói về mặt đường và lề đường, phương án C chỉ nói phần đường xe cơ giới — đều không phải khái niệm chung đúng.' WHERE id = 1;
UPDATE questions SET explanation = 'Làn đường là một phần của phần đường xe chạy được chia theo chiều dọc của đường, có đủ chiều rộng cho xe chạy an toàn. Phương án A thiếu yếu tố "có đủ chiều rộng cho xe chạy an toàn"; phương án C mô tả không đúng bản chất làn đường.' WHERE id = 2;
UPDATE questions SET explanation = 'Khổ giới hạn của đường bộ là khoảng trống có kích thước giới hạn về chiều rộng, chiều cao của đường bộ để các xe, kể cả hàng hoá xếp trên xe đi qua được an toàn, được xác định theo quy chuẩn, tiêu chuẩn kỹ thuật. Các phương án B, C chỉ nêu chiều rộng hoặc chiều cao, thiếu tính đầy đủ.' WHERE id = 3;
UPDATE questions SET explanation = 'Dải phân cách có tác dụng phân chia phần đường xe chạy thành hai chiều riêng biệt hoặc phân chia phần đường dành cho xe cơ giới và xe thô sơ hoặc nhiều loại xe khác nhau trên cùng một chiều đường. Phương án A và C chỉ nêu một phần công dụng.' WHERE id = 4;
UPDATE questions SET explanation = 'Vạch kẻ đường là vạch chỉ sự phân chia làn đường, vị trí hoặc hướng đi, vị trí dừng lại. Vạch kẻ không phải để cảnh báo nguy hiểm (đó là vai trò biển báo) nên phương án A, C, D không đúng.' WHERE id = 5;
UPDATE questions SET explanation = 'Người điều khiển phương tiện tham gia giao thông đường bộ gồm người điều khiển xe cơ giới, người điều khiển xe thô sơ và người điều khiển xe máy chuyên dùng. Phương án B mô tả người được giao nhiệm vụ hướng dẫn giao thông, không phải người điều khiển phương tiện.' WHERE id = 6;
UPDATE questions SET explanation = 'Người lái xe là người điều khiển xe cơ giới. Xe thô sơ và xe máy chuyên dùng có người điều khiển riêng, không gọi là người lái xe theo quy định.' WHERE id = 7;
UPDATE questions SET explanation = 'Xe cơ giới gồm xe ô tô, rơ moóc kéo bởi xe ô tô, sơ mi rơ moóc kéo bởi ô tô đầu kéo, xe chở người 4 bánh có gắn động cơ, xe chở hàng 4 bánh có gắn động cơ, xe mô tô, xe gắn máy và các loại xe tương tự. Xe đạp, xe đạp điện là xe thô sơ nên phương án A không đúng.' WHERE id = 8;
UPDATE questions SET explanation = 'Xe thô sơ gồm xe đạp, xe đạp máy, xe đạp điện, xe xích lô, xe lăn dùng cho người khuyết tật, xe vật nuôi kéo và các loại xe tương tự. Xe gắn máy và xe máy chuyên dùng không thuộc nhóm xe thô sơ.' WHERE id = 9;
UPDATE questions SET explanation = 'Phương tiện giao thông đường bộ gồm cả phương tiện giao thông cơ giới đường bộ và phương tiện giao thông thô sơ đường bộ, xe máy chuyên dùng và các loại xe tương tự. Do đó cả hai ý A và B đều đúng.' WHERE id = 10;
UPDATE questions SET explanation = 'Người tham gia giao thông đường bộ gồm người điều khiển, người được chở trên phương tiện và cả người điều khiển, dẫn dắt vật nuôi, người đi bộ trên đường bộ. Do đó cả hai ý A và B đều đúng.' WHERE id = 11;
UPDATE questions SET explanation = 'Người điều khiển phương tiện tham gia giao thông đường bộ gồm người điều khiển xe cơ giới, người điều khiển xe thô sơ và người điều khiển xe máy chuyên dùng. Do đó cả hai ý A và B đều đúng.' WHERE id = 12;
UPDATE questions SET explanation = 'Người điều khiển giao thông đường bộ là Cảnh sát giao thông và người được giao nhiệm vụ hướng dẫn giao thông trên đường bộ. Đây là lực lượng có thẩm quyền điều khiển, không phải người điều khiển phương tiện.' WHERE id = 13;
UPDATE questions SET explanation = 'Dừng xe là trạng thái đứng yên tạm thời trong khoảng thời gian cần thiết để cho người lên/xuống, xếp dỡ hàng, kiểm tra kỹ thuật; khi dừng xe không được tắt máy và không được rời vị trí lái (trừ các trường hợp đặc biệt). Phương án A, C mô tả "không giới hạn thời gian" là đặc điểm của đỗ xe.' WHERE id = 14;
UPDATE questions SET explanation = 'Đỗ xe là trạng thái đứng yên không giới hạn thời gian; người điều khiển chỉ được rời xe khi đã dùng phanh đỗ hoặc biện pháp an toàn khác; xe đỗ trên đường dốc phải đánh lái về phía lề đường và chèn bánh. Phương án A nói "có giới hạn thời gian" là đặc điểm của dừng xe.' WHERE id = 15;
UPDATE questions SET explanation = 'Đường cao tốc là cấp kỹ thuật cao nhất của đường bộ, chỉ dành cho một số loại xe cơ giới, xe máy chuyên dùng; có dải phân cách chia hai chiều riêng biệt, không giao cắt cùng mức, chỉ cho xe ra vào ở những điểm nhất định và có hàng rào bảo vệ. Phương án B mô tả đường quốc lộ, không phải đường cao tốc.' WHERE id = 16;
UPDATE questions SET explanation = 'Thiết bị an toàn cho trẻ em là thiết bị bảo đảm an toàn cho trẻ em ở tư thế ngồi hoặc nằm trên xe ô tô, thiết kế để giảm nguy cơ chấn thương khi xảy ra va chạm hoặc xe giảm tốc đột ngột. Phương án B nói "tư thế đứng" và "lưu thông bình thường" là không đúng.' WHERE id = 17;
UPDATE questions SET explanation = 'Theo chức năng phục vụ, đường bộ được phân loại thành: đường chính, đường nhánh, đường gom, đường bên, đường dành cho giao thông công cộng, đường nội bộ, đường dành riêng cho người đi bộ, người đi xe đạp và các đường khác. Phương án B, C thiếu "đường bên" hoặc "đường dành cho giao thông công cộng" nên không đầy đủ.' WHERE id = 18;
UPDATE questions SET explanation = 'Rải vật sắc nhọn, đổ chất gây trơn trượt trên đường bộ là hành vi bị nghiêm cấm vì gây nguy hiểm cho người và phương tiện. Việc đi xe đạp trên quốc lộ không bị cấm chung.' WHERE id = 19;
UPDATE questions SET explanation = 'Đưa xe cơ giới, xe máy chuyên dùng tham gia giao thông khi không có chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường hoặc khi đã hết niên hạn sử dụng đều bị cấm. Do đó cả hai ý A và B đều đúng.' WHERE id = 20;
UPDATE questions SET explanation = 'Tổ chức đua xe chỉ được thực hiện khi được cơ quan có thẩm quyền cấp phép. Tự ý tổ chức đua xe trên đường là hành vi vi phạm pháp luật.' WHERE id = 21;
UPDATE questions SET explanation = 'Đua xe trái phép bị xử lý tùy theo mức độ vi phạm, có thể bị xử lý hành chính hoặc xử lý hình sự. Đây là hành vi nguy hiểm nên bị xử lý nghiêm, không chỉ nhắc nhở.' WHERE id = 22;
UPDATE questions SET explanation = 'Điều khiển xe ô tô và xe tương tự khi trong cơ thể có chất ma túy bị phạt tiền đồng thời bị tước giấy phép lái xe. Do đó cả hai ý A và B đều đúng.' WHERE id = 23;
UPDATE questions SET explanation = 'Điều khiển phương tiện khi trong máu hoặc hơi thở có nồng độ cồn là hành vi bị nghiêm cấm tuyệt đối, dù nồng độ nhẹ. Do đó chỉ phương án A đúng.' WHERE id = 24;
UPDATE questions SET explanation = 'Người điều khiển xe ô tô và xe tương tự mà trong máu hoặc hơi thở có nồng độ cồn bị phạt tiền và có thể bị tước giấy phép lái xe. Do đó cả hai ý A và B đều đúng.' WHERE id = 25;
UPDATE questions SET explanation = 'Theo Luật Phòng, chống tác hại của rượu, bia, người điều khiển xe ô tô, xe mô tô, xe đạp, xe gắn máy bị cấm sử dụng rượu, bia khi tham gia giao thông. Người được chở không bị cấm trong quy định này.' WHERE id = 26;
UPDATE questions SET explanation = 'Giao xe cho người chưa đủ tuổi theo quy định, người không có giấy phép lái xe hoặc người có giấy phép nhưng đã bị trừ hết 12 điểm đều là hành vi bị nghiêm cấm. Do đó cả ba ý đều đúng.' WHERE id = 27;
UPDATE questions SET explanation = 'Điều khiển xe cơ giới lạng lách, đánh võng, rú ga liên tục và xúc phạm, đe dọa, chống đối người thi hành công vụ đều là hành vi bị nghiêm cấm. Do đó cả hai ý A và B đều đúng.' WHERE id = 28;
UPDATE questions SET explanation = 'Cải tạo trái phép, cố ý làm sai lệch đồng hồ báo quãng đường, cắt hàn tẩy xóa số khung số máy là hành vi bị cấm đối với phương tiện. Cải tạo xe ô tô thành xe chở người phục vụ quốc phòng, an ninh không nằm trong các hành vi bị cấm.' WHERE id = 29;
UPDATE questions SET explanation = 'Lắp đặt, sử dụng thiết bị âm thanh, ánh sáng gây mất trật tự an toàn giao thông và cản trở người, phương tiện giao thông, ném vật thể vào người, phương tiện đang tham gia giao thông đều bị cấm. Do đó cả hai ý A và B đều đúng.' WHERE id = 30;
UPDATE questions SET explanation = 'Việc sản xuất, sử dụng, mua, bán trái phép biển số xe bị nghiêm cấm hoàn toàn theo quy định của pháp luật.' WHERE id = 31;
UPDATE questions SET explanation = 'Lạng lách, đánh võng, rú ga liên tục là hành vi bị nghiêm cấm khi điều khiển phương tiện tham gia giao thông. Thay đổi tốc độ nhiều lần hay điều khiển sau 23 giờ không bị cấm.' WHERE id = 32;
UPDATE questions SET explanation = 'Hệ thống biển báo hiệu đường bộ gồm năm nhóm: biển báo cấm, biển báo nguy hiểm, biển hiệu lệnh, biển chỉ dẫn và biển phụ. Các phương án nêu 3 hoặc 4 nhóm là thiếu.' WHERE id = 33;
UPDATE questions SET explanation = 'Tại nơi có vạch kẻ đường hoặc nơi người đi bộ, xe lăn của người khuyết tật đang qua đường, người điều khiển phải quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn. Phương án C tăng tốc vượt qua là nguy hiểm, sai quy tắc.' WHERE id = 34;
UPDATE questions SET explanation = 'Người điều khiển xe mô tô phải quan sát, giảm tốc độ hoặc dừng lại khi gặp đường hẹp, đường vòng, đường quanh co, đèo dốc, cầu cống hẹp, trời mưa, sương mù, mặt đường trơn trượt,... Do đó cả ba ý đều đúng.' WHERE id = 35;
UPDATE questions SET explanation = 'Khi Cảnh sát giao thông giơ tay thẳng đứng (tín hiệu dừng), người ở phía trước và phía sau người điều khiển phải dừng lại, còn người ở phía bên phải và bên trái được đi tất cả các hướng. Đây là quy tắc về tín hiệu giao thông bằng tay.' WHERE id = 36;
UPDATE questions SET explanation = 'Khi Cảnh sát giao thông đưa gậy chỉ, các hướng được phép đi theo chiều gậy chỉ của Cảnh sát giao thông, các hướng còn lại phải dừng lại.' WHERE id = 37;
UPDATE questions SET explanation = 'Khi hiệu lệnh của người điều khiển giao thông trái với tín hiệu đèn hoặc biển báo thì người tham gia giao thông phải chấp hành theo hiệu lệnh của người điều khiển giao thông.' WHERE id = 38;
UPDATE questions SET explanation = 'Khi có biển báo hiệu tạm thời và biển báo hiệu đặt cố định có ý nghĩa khác nhau, người tham gia giao thông phải chấp hành theo biển báo hiệu tạm thời vì nó phản ánh tình trạng giao thông thời điểm hiện tại.' WHERE id = 39;
UPDATE questions SET explanation = 'Khi đèn tín hiệu chuyển sang màu vàng, người điều khiển phải dừng lại trước vạch dừng; nếu đã đi qua vạch dừng hoặc đang ở trên vạch dừng thì được đi tiếp. Đèn vàng nhấp nháy được đi nhưng phải quan sát, giảm tốc độ, nhường đường cho người đi bộ.' WHERE id = 40;
UPDATE questions SET explanation = 'Người lái xe phải chấp hành quy định về tốc độ, không được vượt quá tốc độ tối đa cho phép trên từng loại đường, dù đường vắng hay ban đêm.' WHERE id = 41;
UPDATE questions SET explanation = 'Khi chở trẻ em dưới 10 tuổi và dưới 1,35 mét trên xe ô tô, không được cho trẻ ngồi cùng hàng ghế với người lái xe (trừ xe chỉ có một hàng ghế) và phải sử dụng, hướng dẫn sử dụng thiết bị an toàn phù hợp cho trẻ.' WHERE id = 42;
UPDATE questions SET explanation = 'Phương tiện di chuyển với tốc độ thấp hơn phải đi về bên phải theo chiều đi của mình để nhường đường cho phương tiện nhanh hơn, bảo đảm giao thông trật tự an toàn.' WHERE id = 43;
UPDATE questions SET explanation = 'Trên một chiều đường có vạch kẻ phân làn, người điều khiển xe cơ giới, xe máy chuyên dùng phải đi trên làn đường bên phải trong cùng theo chiều đi. Không được tùy ý chọn làn.' WHERE id = 44;
UPDATE questions SET explanation = 'Người lái xe phải giảm tốc độ, có tín hiệu rẽ phải và đi sát về bên phải của phần đường xe chạy khi xe sau xin vượt nếu đủ điều kiện an toàn, để xe phía sau vượt lên được an toàn.' WHERE id = 45;
UPDATE questions SET explanation = 'Vượt xe là tình huống trên đường mà mỗi chiều đường xe chạy chỉ có một làn đường dành cho xe cơ giới, xe đi phía sau di chuyển sang bên trái để lên trước xe phía trước. Phương án B mô tả việc chuyển làn trên đường nhiều làn cùng chiều, không phải vượt xe theo định nghĩa.' WHERE id = 46;
UPDATE questions SET explanation = 'Không được vượt xe trên cầu hẹp có một làn đường, đường cong có tầm nhìn bị hạn chế vì không đủ điều kiện an toàn, dễ gây tai nạn. Việc vượt xe chỉ được thực hiện khi bảo đảm điều kiện an toàn.' WHERE id = 47;
UPDATE questions SET explanation = 'Muốn vượt xe phía trước, người lái xe mô tô phải báo hiệu nhấp nháy bằng đèn chiếu sáng phía trước hoặc còi để xe phía trước biết. Bấm còi liên tục hoặc rú ga liên tục là hành vi bị nghiêm cấm.' WHERE id = 48;
UPDATE questions SET explanation = 'Trong khu đông dân cư, khu vực cơ sở khám bệnh, chữa bệnh (trừ nơi có biển cấm sử dụng còi), người lái xe chỉ được sử dụng còi từ 05 giờ đến 22 giờ để bảo đảm không ảnh hưởng đến giấc ngủ của người dân.' WHERE id = 49;
UPDATE questions SET explanation = 'Phương tiện chỉ được sử dụng tín hiệu còi để báo hiệu cho người tham gia giao thông khi xuất hiện tình huống có thể mất an toàn giao thông hoặc báo hiệu chuẩn bị vượt xe. Việc dùng còi vào ban đêm trong khu dân cư là hành vi bị cấm.' WHERE id = 50;
UPDATE questions SET explanation = 'Trên đoạn đường qua khu đông dân cư có hệ thống chiếu sáng đang hoạt động, người lái xe chỉ được bật đèn chiếu gần (đèn cốt) để không gây chói mắt cho phương tiện đi ngược chiều và người đi bộ. Không được dùng đèn chiếu xa (đèn pha).' WHERE id = 51;
UPDATE questions SET explanation = 'Dùng tay cầm và sử dụng điện thoại hoặc thiết bị điện tử khác khi điều khiển phương tiện là hành vi bị cấm vì gây mất tập trung, nguy hiểm. Chở người trên thùng xe ô tô chở hàng trong trường hợp khẩn cấp theo quy định là được phép.' WHERE id = 52;
UPDATE questions SET explanation = 'Không được vượt xe trên cầu hẹp có một làn đường, nơi đường giao nhau, nơi giao cắt với đường sắt, khi gặp xe ưu tiên. Trên cầu từ 02 làn trở lên hoặc đường nhiều làn có vạch kẻ nét đứt thì vẫn phải tuân thủ quy tắc vượt an toàn, không bị cấm tuyệt đối.' WHERE id = 53;
UPDATE questions SET explanation = 'Cấm quay đầu xe ở phần đường dành cho người đi bộ qua đường, trên cầu, đầu cầu, gầm cầu vượt, ngầm; nơi đường bộ giao nhau cùng mức với đường sắt, đường hẹp, đường dốc, đoạn đường cong tầm nhìn bị che khuất, trên đường cao tốc, trong hầm đường bộ, trên đường một chiều. Do đó cả hai ý đều đúng.' WHERE id = 54;
UPDATE questions SET explanation = 'Người lái xe không được quay đầu xe ở phần đường dành cho người đi bộ qua đường, trên cầu, đầu cầu, trên đường cao tốc, nơi giao cắt cùng mức với đường sắt, đường hẹp, đường dốc. Các vị trí này tiềm ẩn nguy hiểm cao.' WHERE id = 55;
UPDATE questions SET explanation = 'Trước khi chuyển hướng, người lái xe phải quan sát, bảo đảm khoảng cách an toàn với xe phía sau, giảm tốc độ, có tín hiệu báo hướng rẽ và chuyển dần sang làn gần nhất với hướng rẽ, chỉ chuyển hướng khi bảo đảm an toàn. Do đó cả ba ý đều đúng.' WHERE id = 56;
UPDATE questions SET explanation = 'Khi chuyển làn đường, người lái xe phải bật đèn tín hiệu báo rẽ trước khi thay đổi làn đường để các phương tiện khác biết và kịp xử lý.' WHERE id = 57;
UPDATE questions SET explanation = 'Không được lùi xe ở đường một chiều, khu vực cấm dừng, trên phần đường dành cho người đi bộ qua đường; nơi đường giao nhau, giao nhau cùng mức với đường sắt; nơi tầm nhìn bị che khuất, trong hầm đường bộ, trên đường cao tốc. Do đó cả ba ý đều đúng.' WHERE id = 58;
UPDATE questions SET explanation = 'Không được dừng xe, đỗ xe trên miệng cống thoát nước, miệng hầm của đường điện thoại, điện cao thế, chỗ dành riêng cho xe chữa cháy lấy nước và trong phạm vi an toàn của đường sắt. Do đó cả hai ý đều đúng.' WHERE id = 59;
UPDATE questions SET explanation = 'Trên đường phố, xe dừng, đỗ sát theo lề đường, vỉa hè phía bên phải theo chiều đi, bánh xe gần nhất không được cách xa lề đường, vỉa hè quá 0,25 mét và không gây cản trở, nguy hiểm.' WHERE id = 60;
UPDATE questions SET explanation = 'Trên đường phố hẹp, xe ô tô dừng, đỗ phải cách xe ô tô đang đỗ ngược chiều tối thiểu 20 mét để bảo đảm không gian cho các phương tiện khác lưu thông an toàn.' WHERE id = 61;
UPDATE questions SET explanation = 'Không được dừng, đỗ xe song song cùng chiều với một xe khác đang dừng, đỗ trên đường; trên đoạn đường cong hoặc gần đầu dốc mà tầm nhìn bị che khuất; bên trái đường một chiều. Dừng đỗ ở nơi có lề đường rộng là được phép.' WHERE id = 62;
UPDATE questions SET explanation = 'Người điều khiển xe mô tô hai bánh, ba bánh, xe gắn máy không được sử dụng xe để kéo hoặc đẩy các phương tiện khác khi tham gia giao thông.' WHERE id = 63;
UPDATE questions SET explanation = 'Buông cả hai tay, đứng hoặc nằm trên xe điều khiển, sử dụng chân chống hoặc vật khác quệt xuống đường khi xe đang chạy là những hành vi không được phép. Chở hai người trong trường hợp khẩn cấp theo quy định là được phép.' WHERE id = 64;
UPDATE questions SET explanation = 'Buông cả hai tay, sử dụng xe để kéo đẩy xe khác, sử dụng chân chống quệt xuống đường khi xe đang chạy là những hành vi không được phép. Đội mũ bảo hiểm, chạy đúng tốc độ là quy định bắt buộc, không phải hành vi bị cấm.' WHERE id = 65;
UPDATE questions SET explanation = 'Người được chở trên xe mô tô, xe gắn máy không được mang, vác vật cồng kềnh và không được bám, kéo hoặc đẩy các phương tiện khác. Do đó đáp án là ý 1 và ý 2 (D).' WHERE id = 66;
UPDATE questions SET explanation = 'Người được chở trên xe mô tô, xe gắn máy không được bám, kéo hoặc đẩy các phương tiện khác trong mọi trường hợp.' WHERE id = 67;
UPDATE questions SET explanation = 'Người lái xe và người được chở trên xe mô tô, xe gắn máy phải đội mũ bảo hiểm theo đúng quy chuẩn kỹ thuật quốc gia và cài quai đúng quy cách.' WHERE id = 68;
UPDATE questions SET explanation = 'Người lái xe mô tô hai bánh, xe gắn máy được phép chở tối đa hai người khi chở người bệnh đi cấp cứu, áp giải người vi phạm pháp luật, trẻ em dưới 12 tuổi, người già yếu hoặc người khuyết tật. Chở người đã uống rượu bia, có ma túy là bị cấm.' WHERE id = 69;
UPDATE questions SET explanation = 'Người lái xe mô tô, xe gắn máy không được: đi xe dàn hàng ngang, buông cả hai tay; kéo đẩy xe khác, dẫn dắt vật nuôi, mang vác vật cồng kềnh, chở người đứng trên xe, ngồi trên tay lái; ngồi một bên, đứng nằm trên xe điều khiển, quay người phía sau điều khiển, dùng chân chống quệt xuống đường... Do đó cả ba ý đều đúng.' WHERE id = 70;
UPDATE questions SET explanation = 'Người lái xe mô tô, xe gắn máy không được đi xe dàn hàng ngang, đi vào phần đường dành cho người đi bộ và phương tiện khác; không được sử dụng ô, thiết bị âm thanh (trừ thiết bị trợ thính). Do đó cả hai ý đều đúng.' WHERE id = 71;
UPDATE questions SET explanation = 'Đi xe dàn hàng ngang, đi vào phần đường dành cho người đi bộ là hành vi bị cấm. Đi đúng phần đường, làn đường và chấp hành hiệu lệnh là quy định phải tuân thủ, không phải hành vi bị cấm.' WHERE id = 72;
UPDATE questions SET explanation = 'Người được chở trên xe mô tô, xe gắn máy không được sử dụng ô khi tham gia giao thông, kể cả khi trời mưa, vì che khuất tầm nhìn và gây nguy hiểm.' WHERE id = 73;
UPDATE questions SET explanation = 'Người được chở trên xe mô tô không được kéo theo người điều khiển xe đạp hoặc các phương tiện khác. Hành vi kéo đẩy phương tiện khác bị nghiêm cấm.' WHERE id = 74;
UPDATE questions SET explanation = 'Khi người được chở trên xe mô tô, xe gắn máy không đội mũ bảo hiểm hoặc không cài quai đúng quy cách (trừ trường hợp đặc biệt), người điều khiển và người được chở đều bị xử phạt vi phạm hành chính.' WHERE id = 75;
UPDATE questions SET explanation = 'Để bảo đảm an toàn, người lái xe mô tô phải luôn đội mũ bảo hiểm đúng quy chuẩn và cài quai đúng quy cách, không sử dụng ô, điện thoại di động, thiết bị âm thanh (trừ thiết bị trợ thính).' WHERE id = 76;
UPDATE questions SET explanation = 'Thứ tự xuống phà đúng quy tắc: xe cơ giới, xe máy chuyên dùng xuống trước, xe thô sơ, người đi bộ xuống sau. Do xe thô sơ và người đi bộ di chuyển chậm, cần xuống sau để không cản trở.' WHERE id = 77;
UPDATE questions SET explanation = 'Trên đường có nhiều làn cùng chiều được phân biệt bằng vạch kẻ, xe phải đi trong một làn, chỉ chuyển làn ở nơi cho phép, mỗi lần chuyển sang một làn liền kề, phải có tín hiệu báo trước và quan sát khoảng cách an toàn. Phương án B mô tả đầy đủ và đúng quy tắc.' WHERE id = 78;
UPDATE questions SET explanation = 'Trên đường một chiều có vạch kẻ phân làn, xe thô sơ phải đi trên làn đường bên phải trong cùng, xe cơ giới, xe máy chuyên dùng đi trên làn đường bên trái.' WHERE id = 79;
UPDATE questions SET explanation = 'Trong đô thị và khu đông dân cư từ 22 giờ hôm trước đến 05 giờ hôm sau, khi cần vượt xe khác, người lái xe chỉ được báo hiệu bằng đèn (không được dùng còi vì gây ồn).' WHERE id = 80;
UPDATE questions SET explanation = 'Khi xe sau xin vượt, nếu đủ điều kiện an toàn, người điều khiển phải giảm tốc độ, có tín hiệu rẽ phải báo hiệu cho xe sau biết được vượt, đi sát về bên phải của phần đường xe chạy cho đến khi xe sau vượt qua và không được cản trở.' WHERE id = 81;
UPDATE questions SET explanation = 'Khi xe sau xin vượt nhưng chưa đủ điều kiện an toàn, người điều khiển phải có tín hiệu rẽ trái để báo hiệu cho xe sau biết chưa được vượt.' WHERE id = 82;
UPDATE questions SET explanation = 'Khi chuyển hướng, người lái xe phải nhường đường cho người đi bộ, xe thô sơ, xe đi ngược chiều và chỉ chuyển hướng khi không gây trở ngại hoặc nguy hiểm cho người, phương tiện khác.' WHERE id = 83;
UPDATE questions SET explanation = 'Trước khi chuyển hướng, phải quan sát, bảo đảm khoảng cách an toàn với xe phía sau, giảm tốc độ, có tín hiệu báo hướng rẽ (liên tục trong quá trình chuyển hướng), chuyển dần sang làn gần nhất với hướng rẽ và chỉ chuyển hướng khi bảo đảm an toàn. Phương án B mô tả đầy đủ.' WHERE id = 84;
UPDATE questions SET explanation = 'Khi lùi xe, người điều khiển phải quan sát hai bên và phía sau xe, có tín hiệu lùi và chỉ lùi xe khi bảo đảm an toàn.' WHERE id = 85;
UPDATE questions SET explanation = 'Ở nơi có tầm nhìn bị che khuất, người lái xe không được lùi xe vì không thể bảo đảm an toàn.' WHERE id = 86;
UPDATE questions SET explanation = 'Trên đường không phân chia hai chiều riêng biệt, khi tránh xe đi ngược chiều, người điều khiển phải giảm tốc độ và cho xe đi về bên phải theo chiều xe chạy của mình.' WHERE id = 87;
UPDATE questions SET explanation = 'Khi tránh xe đi ngược chiều: nơi đường hẹp chỉ đủ một xe chạy thì xe ở gần chỗ tránh hơn phải vào vị trí tránh nhường đường; xe xuống dốc nhường đường cho xe lên dốc; xe có chướng ngại vật phía trước nhường đường cho xe không có chướng ngại vật. Do đó cả ba ý đều đúng.' WHERE id = 88;
UPDATE questions SET explanation = 'Xe xuống dốc phải nhường đường cho xe đang lên dốc vì xe lên dốc khó kiểm soát hơn, mất khả năng dừng đỗ dễ dàng.' WHERE id = 89;
UPDATE questions SET explanation = 'Khi lái xe trên đường cong có tầm nhìn bị hạn chế, người lái xe phải quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn, tuyệt đối không đi sang làn ngược chiều để vượt.' WHERE id = 90;
UPDATE questions SET explanation = 'Tại nơi đường giao nhau, xe đi trên đường không ưu tiên (đường nhánh) phải nhường đường cho xe đi trên đường ưu tiên hoặc đường chính từ bất kỳ hướng nào tới.' WHERE id = 91;
