UPDATE questions SET explanation = 'Xe Cảnh sát giao thông không phát tín hiệu ưu tiên là xe bình thường, nên người lái xe được phép vượt khi bảo đảm an toàn theo quy tắc vượt xe.' WHERE id = 97;
UPDATE questions SET explanation = 'Xe cứu thương đang phát tín hiệu ưu tiên là xe ưu tiên đang làm nhiệm vụ, người lái xe không được vượt và phải nhường đường.' WHERE id = 98;
UPDATE questions SET explanation = 'Khi tới đường ngang không có người gác, chắn đường bộ, chuông, đèn tín hiệu, người tham gia giao thông phải dừng lại về bên phải đường của mình, trước vạch dừng xe, quan sát hai phía, khi không có phương tiện giao thông đường sắt tới mới được đi qua.' WHERE id = 99;
UPDATE questions SET explanation = 'Tại đường ngang, cầu chung đường sắt khi có hiệu lệnh của nhân viên gác chắn, đèn đỏ sáng nhấp nháy, chuông kêu, chắn đang dịch chuyển hoặc đã đóng, người tham gia giao thông phải dừng lại về bên phải đường của mình, trước vạch dừng xe.' WHERE id = 100;
UPDATE questions SET explanation = 'Khi xe ô tô bị hư hỏng, bị tai nạn trên đường ngang, cầu chung đường sắt mà không thể di chuyển ngay khỏi phạm vi an toàn đường sắt, người lái xe và người có mặt phải ngay lập tức báo hiệu để dừng tàu và thực hiện các biện pháp bảo đảm an toàn.' WHERE id = 101;
UPDATE questions SET explanation = 'Người tham gia giao thông phải dừng lại về bên phải đường của mình trước vạch dừng xe tại đường ngang, cầu chung đường sắt khi có hiệu lệnh của nhân viên gác chắn, đèn đỏ sáng nhấp nháy/chuông kêu, hoặc chắn đang dịch chuyển/đã đóng. Do đó cả ba ý đều đúng.' WHERE id = 102;
UPDATE questions SET explanation = 'Trong hầm đường bộ: xe cơ giới, xe máy chuyên dùng phải bật đèn chiếu gần; xe thô sơ phải bật đèn hoặc có vật phát sáng; không dừng xe, đỗ xe; nếu gặp sự cố buộc phải dừng phải đưa xe vào vị trí dừng khẩn cấp, báo hiệu bằng đèn khẩn cấp và đặt biển/đèn cảnh báo về phía sau xe khoảng cách bảo đảm an toàn.' WHERE id = 103;
UPDATE questions SET explanation = 'Khi hệ thống hãm của xe được kéo không còn hiệu lực, xe kéo và xe được kéo phải nối với nhau bằng thanh nối cứng để bảo đảm an toàn.' WHERE id = 104;
UPDATE questions SET explanation = 'Xe kéo rơ moóc, xe ô tô đầu kéo chỉ được kéo rơ moóc, sơ mi rơ moóc phù hợp với thiết kế của xe; việc kết nối phải bảo đảm chắc chắn, an toàn.' WHERE id = 105;
UPDATE questions SET explanation = 'Xe được kéo phải có người điều khiển và hệ thống lái còn hiệu lực; nối xe kéo với xe được kéo phải chắc chắn an toàn; nếu hệ thống hãm của xe được kéo không còn hiệu lực thì phải nối bằng thanh nối cứng; phía trước xe kéo và phía sau xe được kéo phải có biển báo hiệu và đèn cảnh báo nhấp nháy màu vàng.' WHERE id = 106;
UPDATE questions SET explanation = 'Phải quan sát, giảm tốc độ hoặc dừng lại khi: có báo hiệu cảnh báo nguy hiểm hoặc chướng ngại vật; nơi cầu cống hẹp, đập tràn, đường ngầm, hầm chui; có vật nuôi đi trên đường; điểm dừng đỗ có khách đang lên xuống xe. Do đó cả ba ý đều đúng.' WHERE id = 107;
UPDATE questions SET explanation = 'Trên đường một chiều xe chạy chỉ có một làn cho xe cơ giới, không được vượt khi có chướng ngại vật phía trước hoặc khi xe phía trước có tín hiệu vượt xe khác.' WHERE id = 108;
UPDATE questions SET explanation = 'Được phép vượt về bên phải khi xe phía trước có tín hiệu rẽ trái hoặc đang rẽ trái, hoặc khi xe chuyên dùng đang làm việc trên đường mà không thể vượt bên trái.' WHERE id = 109;
UPDATE questions SET explanation = 'Khi xe sau xin vượt và đủ điều kiện an toàn, người lái xe mô tô phải giảm tốc độ, có tín hiệu rẽ phải báo hiệu cho xe sau được vượt và đi sát về bên phải của phần đường xe chạy cho đến khi xe sau vượt qua, không được cản trở.' WHERE id = 110;
UPDATE questions SET explanation = 'Không được đi trên đường cao tốc (trừ người, phương tiện, thiết bị phục vụ quản lý, bảo trì): xe máy chuyên dùng có tốc độ thiết kế nhỏ hơn tốc độ tối thiểu quy định, xe chở người/hàng bốn bánh có gắn động cơ, xe mô tô, xe gắn máy và xe tương tự, xe thô sơ, người đi bộ.' WHERE id = 111;
UPDATE questions SET explanation = 'Trên đường cao tốc, xe ưu tiên đi làm nhiệm vụ khẩn cấp chỉ được đi ngược chiều trên làn dừng xe khẩn cấp.' WHERE id = 112;
