UPDATE questions SET explanation = 'Tại những đoạn đường không có biển báo hạn chế tốc độ, không có biển báo khoảng cách an toàn tối thiểu, người lái xe vẫn phải chấp hành quy định về tốc độ và khoảng cách an toàn tối thiểu với xe phía trước cùng làn đường hoặc phần đường.' WHERE id = 166;
UPDATE questions SET explanation = 'Khi gặp xe buýt đang dừng đón, trả khách, người điều khiển xe mô tô phải quan sát, giảm tốc độ đi qua xe buýt hoặc dừng lại để bảo đảm an toàn, vì hành khách có thể đang lên, xuống xe.' WHERE id = 167;
UPDATE questions SET explanation = 'Việc vận chuyển hành khách bằng xe ô tô phải đón, trả hành khách đúng nơi quy định; hướng dẫn sử dụng trang thiết bị an toàn; giữ gìn vệ sinh; vận chuyển đúng lịch trình, lộ trình đã đăng ký (trừ bất khả kháng); không chở khách trên nóc xe, trong khoang hành lý hoặc để khách đu, bám bên ngoài xe.' WHERE id = 168;
UPDATE questions SET explanation = 'Trong hoạt động vận tải đường bộ, các hành vi bị nghiêm cấm gồm: vận chuyển hàng hóa cấm lưu hành; vận chuyển trái phép hoặc không thực hiện đầy đủ quy định về vận chuyển hàng hóa nguy hiểm; vận chuyển động vật hoang dã. Do đó cả ba ý đều đúng.' WHERE id = 169;
UPDATE questions SET explanation = 'Trong hoạt động vận tải hành khách, hành vi bị nghiêm cấm là đe dọa, xúc phạm, tranh giành, lôi kéo hành khách; cưỡng ép hành khách sử dụng dịch vụ ngoài ý muốn; chuyển tải, xuống khách hoặc các hành vi khác nhằm trốn tránh việc phát hiện xe chở quá tải, quá số người.' WHERE id = 170;
UPDATE questions SET explanation = 'Thời gian lái xe liên tục của người lái xe ô tô kinh doanh vận tải không quá 4 giờ, để bảo đảm sự tập trung và an toàn giao thông.' WHERE id = 171;
UPDATE questions SET explanation = 'Thời gian làm việc của người lái xe ô tô kinh doanh vận tải trong một ngày không quá 10 giờ.' WHERE id = 172;
UPDATE questions SET explanation = 'Trước khi xe khởi hành, người lái xe và nhân viên phục vụ trên xe vận chuyển hành khách phải kiểm tra các điều kiện bảo đảm an toàn của xe và hướng dẫn cho hành khách về an toàn giao thông đường bộ và thoát hiểm khi gặp sự cố. Do đó đáp án là ý 1 và ý 2.' WHERE id = 173;
UPDATE questions SET explanation = 'Xe ô tô kinh doanh vận tải chở trẻ em mầm non, học sinh phải có thiết bị ghi nhận hình ảnh trẻ em và thiết bị cảnh báo chống bỏ quên trẻ, niên hạn sử dụng không quá 20 năm, có màu sơn theo quy định; có dây đai an toàn hoặc ghế ngồi phù hợp lứa tuổi; được cấp chứng nhận đăng ký, gắn biển số, bảo đảm an toàn kỹ thuật, và xe từ 08 chỗ trở lên phải lắp thiết bị giám sát hành trình. Do đó cả ba ý đều đúng.' WHERE id = 174;
UPDATE questions SET explanation = 'Việc vận chuyển động vật sống phải: mang đủ giấy tờ theo quy định; phương tiện có kết cấu phù hợp với loại động vật chuyên chở; chấp hành quy định về trật tự an toàn giao thông, vệ sinh dịch tễ, phòng dịch và vệ sinh môi trường. Do đó cả ba ý đều đúng.' WHERE id = 175;
UPDATE questions SET explanation = 'Việc vận chuyển hàng hóa nguy hiểm phải có giấy phép vận chuyển; trong trường hợp cần thiết, đơn vị vận chuyển phải bố trí người áp tải để bảo đảm trật tự, an toàn giao thông đường bộ.' WHERE id = 176;
UPDATE questions SET explanation = 'Xe ô tô của người nước ngoài đăng ký tại nước ngoài có tay lái bên phải tham gia giao thông tại Việt Nam phải chấp hành quy định pháp luật của Việt Nam (hoặc điều ước quốc tế nếu có quy định khác), đi đúng phạm vi, tuyến đường, thời gian được cấp phép, và phải đi theo đoàn có người, phương tiện hỗ trợ, hướng dẫn giao thông. Do đó cả ba ý đều đúng.' WHERE id = 177;
UPDATE questions SET explanation = 'Sử dụng xe mô tô, xe gắn máy, xe thô sơ để vận chuyển hành khách, hàng hóa phải kiểm tra điều kiện an toàn của xe trước khi tham gia giao thông, mang đủ giấy tờ, kiểm tra việc sắp xếp hàng hóa, không chở quá số người, quá khối lượng hoặc vượt quá khổ giới hạn. Do đó cả hai ý đều đúng.' WHERE id = 178;
UPDATE questions SET explanation = 'Xe vận chuyển hàng siêu trường, siêu trọng phải chạy với tốc độ quy định trong giấy phép, có báo hiệu kích thước của hàng; trường hợp cần thiết phải có người, phương tiện hỗ trợ lái xe, cảnh báo cho người và phương tiện khác và thực hiện các biện pháp bảo đảm an toàn giao thông.' WHERE id = 179;
UPDATE questions SET explanation = 'Xe cứu hộ giao thông đường bộ phải có dấu hiệu nhận diện, niêm yết thông tin trên xe, gắn thiết bị giám sát hành trình và thiết bị ghi nhận hình ảnh người lái xe, đồng thời phải tuân thủ quy định về khối lượng hàng hóa chuyên chở của xe cứu hộ và khối lượng của xe được cứu hộ. Do đó cả hai ý đều đúng.' WHERE id = 180;
UPDATE questions SET explanation = 'Người lái xe kinh doanh vận tải rèn luyện, nâng cao trách nhiệm và đạo đức nghề nghiệp sẽ được khách hàng, xã hội tôn trọng; được đồng nghiệp quý mến, giúp đỡ; được doanh nghiệp tin dùng, đóng góp cho xã hội, thu hút khách hàng và nâng cao hiệu quả kinh doanh. Đây là lợi ích thiết thực của việc thực hiện tốt đạo đức nghề nghiệp.' WHERE id = 181;
UPDATE questions SET explanation = 'Người có văn hóa giao thông là người luôn tuân thủ pháp luật về trật tự, an toàn giao thông đường bộ, biết nhường nhịn và giúp đỡ người khác. Các hành vi vượt đèn đỏ, bấm còi nháy đèn liên tục, không nhường đường là thiếu văn hóa giao thông.' WHERE id = 182;
UPDATE questions SET explanation = 'Người lái xe kinh doanh vận tải cần rèn luyện đạo đức nghề nghiệp qua việc: quản lý và sử dụng xe tốt, bảo dưỡng đúng định kỳ, tiết kiệm vật tư nhiên liệu, có lối sống lành mạnh, tác phong công nghiệp; nắm vững và tự giác chấp hành pháp luật về an toàn giao thông, thực hiện đầy đủ trách nhiệm với khách hàng, có ý thức kỷ luật, hợp tác giúp đỡ đồng nghiệp. Do đó cả hai ý đều đúng.' WHERE id = 183;
UPDATE questions SET explanation = 'Người lái xe vận chuyển hành khách phải có thái độ lịch sự, tôn trọng, thân mật với hành khách, giúp đỡ người khó khăn, người già, người khuyết tật, phụ nữ có thai, trẻ em; luôn tu dưỡng bản thân, lối sống lành mạnh, tác phong công nghiệp, không tham gia tệ nạn xã hội, tôn trọng người cùng tham gia giao thông và có ý thức bảo vệ môi trường. Do đó cả hai ý đều đúng.' WHERE id = 184;
UPDATE questions SET explanation = 'Văn hóa giao thông là sự hiểu biết và chấp hành nghiêm chỉnh pháp luật về giao thông, ý thức trách nhiệm với cộng đồng, đồng thời là sự tôn trọng, nhường nhịn, giúp đỡ và ứng xử có văn hóa giữa những người tham gia giao thông. Do đó cả hai ý đều đúng.' WHERE id = 185;
UPDATE questions SET explanation = 'Khi phải đi qua vũng nước trên làn đường ô tô và bên cạnh có người điều khiển xe mô tô, người lái xe có văn hóa giao thông phải giảm tốc độ cho xe chạy chậm qua vũng nước để tránh hắt nước, bùn vào người đi xe mô tô.' WHERE id = 186;
UPDATE questions SET explanation = 'Đi không đúng làn đường, phóng nhanh, vượt ẩu, vượt đèn đỏ, đi vào đường cấm là hành vi thiếu văn hóa giao thông và vi phạm pháp luật về trật tự, an toàn giao thông đường bộ.' WHERE id = 187;
UPDATE questions SET explanation = 'Khi nạn nhân có vết thương chảy máu phun thành tia, phun mạnh theo nhịp mạch đập (chảy máu động mạch), phải thực hiện cầm máu không trực tiếp (chặn động mạch ở phía trên vết thương), vì cầm máu trực tiếp không đủ hiệu quả với vết thương động mạch.' WHERE id = 188;
UPDATE questions SET explanation = 'Người lái xe có văn hóa giao thông phải hiểu biết và chấp hành nghiêm chỉnh pháp luật giao thông, có ý thức trách nhiệm với cộng đồng, tôn trọng, nhường nhịn, giúp đỡ và ứng xử có văn hóa với người cùng tham gia giao thông. Vượt quá tốc độ, đi không đúng làn đường là hành vi ngược lại.' WHERE id = 189;
UPDATE questions SET explanation = 'Người lái xe có văn hóa giao thông phải chấp hành hiệu lệnh, chỉ dẫn của người điều khiển giao thông, quy định về tốc độ, tín hiệu đèn, biển báo, vạch kẻ đường và nhường đường cho người đi bộ, người già, trẻ em, người khuyết tật.' WHERE id = 190;
UPDATE questions SET explanation = 'Người lái xe mô tô có văn hóa giao thông phải điều khiển xe đi bên phải theo chiều đi, đi đúng phần đường, làn đường quy định, đội mũ bảo hiểm đúng quy chuẩn kỹ thuật quốc gia và cài quai đúng quy cách.' WHERE id = 191;
UPDATE questions SET explanation = 'Người lái xe có văn hóa giao thông phải điều khiển xe đi bên phải theo chiều đi, đi đúng phần đường, làn đường quy định, dừng, đỗ xe đúng nơi quy định và đã uống rượu, bia thì không lái xe.' WHERE id = 192;
UPDATE questions SET explanation = 'Sử dụng còi có văn hóa giao thông là chỉ bấm còi khi thật sự cần thiết, không bấm còi liên tục hoặc kéo dài, sử dụng còi với mức âm lượng theo quy định. Không bấm còi to ở khu đông dân cư, cũng không cần thiết phải tuyệt đối không dùng còi.' WHERE id = 193;
UPDATE questions SET explanation = 'Người gây tai nạn và người liên quan phải: dừng ngay phương tiện, cảnh báo nguy hiểm, giữ nguyên hiện trường, trợ giúp người bị nạn và báo tin cho cơ quan Công an, cơ sở khám chữa bệnh; ở lại hiện trường cho đến khi Công an đến (trừ trường hợp phải đi cấp cứu nhưng phải đến trình báo ngay); cung cấp thông tin xác định danh tính và thông tin liên quan vụ tai nạn cho cơ quan có thẩm quyền. Do đó cả ba ý đều đúng.' WHERE id = 194;
UPDATE questions SET explanation = 'Người có mặt tại nơi xảy ra tai nạn có trách nhiệm giúp đỡ, cứu chữa kịp thời người bị nạn; báo tin ngay cho cơ quan Công an, cơ sở khám chữa bệnh hoặc Ủy ban nhân dân nơi gần nhất; tham gia bảo vệ hiện trường và bảo vệ tài sản của người bị nạn; cung cấp thông tin liên quan theo yêu cầu của cơ quan có thẩm quyền.' WHERE id = 195;
UPDATE questions SET explanation = 'Khi sơ cứu ban đầu cho người bị tai nạn không còn hô hấp, phải đặt nạn nhân nằm ngửa, khai thông đường thở và thực hiện các biện pháp hô hấp nhân tạo để duy trì sự sống trước khi chuyển đến cơ sở y tế.' WHERE id = 196;
UPDATE questions SET explanation = 'Bỏ trốn sau khi gây tai nạn để trốn tránh trách nhiệm hoặc có điều kiện mà cố ý không cứu giúp người bị tai nạn là hành vi bị nghiêm cấm.' WHERE id = 197;
UPDATE questions SET explanation = 'Khi thấy người đi bộ đang sang đường trên vạch kẻ dành cho người đi bộ, người lái xe phải giảm tốc độ và nhường đường cho người đi bộ, không bấm còi thúc giục hay cố vượt qua.' WHERE id = 198;
UPDATE questions SET explanation = 'Khi gặp vụ tai nạn giao thông, người lái xe nên dừng xe, hỗ trợ nạn nhân và báo cho cơ quan chức năng, không chạy trốn hay chỉ quan sát rồi đi tiếp.' WHERE id = 199;
UPDATE questions SET explanation = 'Trong đoạn đường hai chiều tại khu đông dân cư đang ùn tắc, người có văn hóa giao thông sẽ kiên nhẫn tuân thủ hướng dẫn của người điều khiển giao thông hoặc tín hiệu đèn giao thông, di chuyển trên đúng phần đường bên phải theo chiều đi và nhường đường cho các phương tiện đi ngược chiều, không lấn sang làn ngược chiều hay đi trên vỉa hè.' WHERE id = 200;
UPDATE questions SET explanation = 'Hành vi thiếu văn hóa khi ùn tắc gồm: bấm còi liên tục thúc giục, đi trên vỉa hè, tận dụng mọi khoảng trống để thoát khỏi ùn tắc, lấn sang trái đường vượt lên xe khác. Tuân thủ hướng dẫn và đi đúng phần đường, làn đường là hành vi có văn hóa.' WHERE id = 201;
UPDATE questions SET explanation = 'Biện pháp phòng cháy chữa cháy đối với phương tiện giao thông cơ giới gồm: không lắp đặt thiết bị điện, phụ kiện không đúng thiết kế; tuân thủ quy trình bảo trì bảo dưỡng, thường xuyên kiểm tra và khắc phục ngay dấu hiệu bất thường; tắt khóa điện khi để xe, không mua xăng dầu không rõ nguồn gốc, không dùng biện pháp tiết kiệm xăng dầu chưa kiểm chứng; không để chất dễ cháy trong xe, chọn nơi sạc an toàn cho xe điện. Do đó cả ba ý đều đúng.' WHERE id = 202;
UPDATE questions SET explanation = 'Khi phương tiện bị cháy có khả năng dập tắt: tắt khóa điện, hô hoán để mọi người trợ giúp, gọi Cảnh sát PCCC và CNCH (114); nếu nhiên liệu chưa trào ra ngoài có thể dùng nước dập lửa, nếu nhiên liệu đã trào ra ngoài (cháy dữ dội) phải dùng bình chữa cháy, cát, chăn nhúng nước để dập lửa. Do đó cả hai ý đều đúng.' WHERE id = 203;
UPDATE questions SET explanation = 'Khi phát hiện lửa, khói hoặc nhiệt độ cao bất thường từ xe, việc đầu tiên phải bình tĩnh đưa xe sát vào lề đường, tránh xa nơi đông người và chất dễ cháy, tắt khóa điện rồi thực hiện các bước chữa cháy.' WHERE id = 204;
UPDATE questions SET explanation = 'Khi gặp nạn nhân bị bỏng trong tai nạn giao thông, cần gọi số 115 để thông báo và yêu cầu hỗ trợ y tế, quan sát hiện trường để giúp nạn nhân tránh gây tổn thương cho mình; nhanh chóng loại bỏ nguyên nhân gây bỏng, ngâm vùng da bị bỏng vào nước sạch hoặc đắp khăn mát (không dùng nước hoặc khăn quá lạnh); nếu nạn nhân còn tỉnh cho uống bù nước, giữ ấm trong thời tiết lạnh rồi đưa đến cơ sở y tế gần nhất. Do đó cả ba ý đều đúng.' WHERE id = 205;
UPDATE questions SET explanation = 'Khi xuống dốc dài, độ dốc cao bằng xe mô tô tay ga, người lái xe cần giữ tay ga ở mức độ phù hợp, kết hợp sử dụng cả phanh trước và phanh sau để giảm tốc độ. Không tắt động cơ hay tắt chìa khóa điện vì có thể làm mất khả năng điều khiển.' WHERE id = 206;
UPDATE questions SET explanation = 'Khi vào số khởi hành xe ô tô số tự động, phải đạp bàn đạp phanh chân hết hành trình, vào số, nhả phanh đỗ, kiểm tra xem có bị nhầm số không rồi mới cho xe lăn bánh để bảo đảm an toàn.' WHERE id = 207;
UPDATE questions SET explanation = 'Khi nhả phanh đỗ cơ khí điều khiển bằng tay, dùng lực tay phải bóp khóa hãm và đẩy cần phanh tay về phía trước hết hành trình; nếu khóa hãm bị kẹt cứng phải kéo cần phanh tay về phía sau đồng thời bóp khóa hãm.' WHERE id = 208;
UPDATE questions SET explanation = 'Khi khởi hành ô tô số cơ khí trên đường bằng: kiểm tra an toàn xung quanh; đạp ly hợp (côn) hết hành trình; vào số 1; nhả hết phanh tay, báo hiệu bằng còi, đèn; tăng ga đủ để xuất phát; nhả côn từ từ đến 1/2 hành trình và giữ khoảng 3 giây, sau đó vừa tăng ga vừa nhả hết côn để xe chuyển động. Trình tự ở phương án B là đúng.' WHERE id = 209;
UPDATE questions SET explanation = 'Khi quay đầu xe: quan sát biển báo để biết nơi được phép quay đầu; quan sát kỹ địa hình; lựa chọn quỹ đạo quay đầu thích hợp; quay đầu với tốc độ thấp; thường xuyên báo tín hiệu cho người, phương tiện xung quanh; nếu quay đầu ở nơi nguy hiểm thì đưa đầu xe về phía nguy hiểm và đuôi xe về phía an toàn.' WHERE id = 210;
UPDATE questions SET explanation = 'Khi ngồi lái ô tô, cần điều chỉnh ghế sao cho chân có thể đạp phanh và ga dễ dàng, ngồi thẳng lưng, hai tay nắm vô lăng, tay trái nắm ở vị trí 9-10 giờ và tay phải nắm ở vị trí 2-4 giờ để bảo đảm an toàn và thoải mái.' WHERE id = 211;
UPDATE questions SET explanation = 'Khi điều khiển ô tô lên dốc cao, cần về số thấp từ chân dốc, điều chỉnh ga cho xe từ từ lên dốc; đến gần đỉnh dốc phải đi chậm, đi sát về phía bên phải đường và có tín hiệu (còi, đèn) để báo cho xe đi ngược chiều biết.' WHERE id = 212;
UPDATE questions SET explanation = 'Khi điều khiển ô tô xuống dốc dài, cần về số thấp, nhả bàn đạp ga ở mức độ phù hợp, kết hợp với phanh chân để khống chế tốc độ, tránh việc đạp phanh liên tục gây cháy phanh hoặc mất hiệu quả phanh.' WHERE id = 213;
UPDATE questions SET explanation = 'Khi xuống dốc muốn dừng xe: có tín hiệu rẽ phải, điều khiển xe sát vào lề đường bên phải; đạp phanh sớm và mạnh hơn lúc dừng trên đường bằng; về số 1, đạp 1/2 ly hợp cho xe đến chỗ dừng; khi xe đã dừng, về số không (N), đạp phanh chân và sử dụng phanh đỗ.' WHERE id = 214;
UPDATE questions SET explanation = 'Khi điều khiển xe trên đường vòng, cần quan sát cẩn thận chướng ngại vật, báo hiệu bằng còi, đèn; giảm tốc độ tới mức cần thiết, về số thấp và quay vòng với tốc độ phù hợp với bán kính cong của đường vòng.' WHERE id = 215;
UPDATE questions SET explanation = 'Khi rẽ phải: cách chỗ rẽ một khoảng cách an toàn có tín hiệu rẽ phải; giảm tốc độ, quan sát an toàn phía trước, sau, bên phải và điều khiển xe từ từ rẽ phải.' WHERE id = 216;
UPDATE questions SET explanation = 'Khi rẽ trái: cách chỗ rẽ một khoảng cách an toàn có tín hiệu rẽ trái; giảm tốc độ, quan sát an toàn xung quanh đặc biệt là bên trái; đổi sang làn đường bên trái và điều khiển xe từ từ rẽ trái.' WHERE id = 217;
UPDATE questions SET explanation = 'Khi vượt qua rãnh lớn cắt ngang mặt đường bằng xe số cơ khí: vào số 1 và từ từ cho hai bánh xe trước xuống rãnh, tăng ga cho hai bánh xe trước vượt lên khỏi rãnh, tiếp tục để bánh xe sau từ từ xuống rãnh rồi tăng dần ga cho xe lên khỏi rãnh.' WHERE id = 218;
UPDATE questions SET explanation = 'Khi điều khiển xe qua đường sắt: nếu có chuông báo hoặc thanh chắn đã hạ xuống thì dừng xe tạm thời đúng khoảng cách an toàn, kéo phanh tay nếu đường dốc hoặc phải chờ lâu; nếu không có chuông báo hoặc thanh chắn không hạ xuống thì quan sát, nếu đủ điều kiện an toàn thì về số thấp, tăng ga nhẹ và không thay đổi số trong quá trình vượt qua để tránh động cơ chết máy. Do đó cả hai ý đều đúng.' WHERE id = 219;
UPDATE questions SET explanation = 'Khi điều khiển xe ô tô tự đổ cần chú ý: trên đường xấu nhiều ổ gà nên chạy chậm để thùng xe không bị lắc mạnh, tránh lệch "ben"; khi vào đường vòng cần giảm tốc độ, không lấy lái gấp, không phanh gấp; khi đổ hàng phải chọn vị trí nền đường cứng phẳng, dừng hẳn, kéo hết phanh đỗ rồi mới nâng "ben" đổ hàng, đổ xong mới hạ thùng. Do đó đáp án là ý 1 và ý 3.' WHERE id = 220;
UPDATE questions SET explanation = 'Khi tăng số, người lái xe không được nhìn xuống buồng lái, phải tăng thứ tự từ thấp đến cao, phối hợp các động tác nhịp nhàng, chính xác.' WHERE id = 221;
UPDATE questions SET explanation = 'Khi giảm số, người lái xe không được nhìn xuống buồng lái, phải giảm thứ tự từ cao xuống thấp, phối hợp các động tác nhịp nhàng, chính xác và vù ga phù hợp với tốc độ.' WHERE id = 222;
UPDATE questions SET explanation = 'Để giảm tốc độ khi ô tô xuống đường dốc dài, người lái xe phải về số thấp phù hợp, nhả bàn đạp ga và kết hợp đạp phanh chân với mức độ phù hợp để giảm tốc độ.' WHERE id = 223;
UPDATE questions SET explanation = 'Khi ô tô qua đường ngập nước, cần quan sát, ước lượng độ ngập nước mà xe có thể vượt qua an toàn, về số thấp, giữ đều ga và giữ vững tay lái để xe vượt qua đoạn đường ngập nước.' WHERE id = 224;
UPDATE questions SET explanation = 'Khi tới gần xe chạy ngược chiều vào ban đêm, cần chuyển từ đèn chiếu xa sang đèn chiếu gần, không nhìn thẳng vào đèn của xe ngược chiều mà nhìn chếch sang phía phải theo chiều chuyển động của xe mình để tránh bị chói mắt.' WHERE id = 225;
UPDATE questions SET explanation = 'Trên đường trơn, cần giữ vững tay lái cho xe đi đúng vệt bánh xe đi trước, sử dụng số thấp đi chậm, gài cầu (nếu có), giữ đều ga, không lấy nhiều lái, không đánh lái ngoặt và không phanh gấp để tránh trượt, văng xe.' WHERE id = 226;
UPDATE questions SET explanation = 'Ký hiệu bảng đồng hồ xuất hiện hình phanh đỗ là báo hiệu đang sử dụng phanh đỗ (phanh tay).' WHERE id = 227;
UPDATE questions SET explanation = 'Ký hiệu hình bình dầu trên bảng đồng hồ báo hiệu áp suất dầu ở mức thấp (thiếu dầu bôi trơn), cần dừng xe kiểm tra ngay.' WHERE id = 228;
UPDATE questions SET explanation = 'Ký hiệu hình cửa xe mở trên bảng đồng hồ báo hiệu cửa xe đóng chưa chặt hoặc có cửa xe chưa đóng.' WHERE id = 229;
UPDATE questions SET explanation = 'Ký hiệu hình người ngồi thắt dây an toàn trên bảng đồng hồ báo hiệu người lái xe và người ngồi ghế trước chưa cài dây đai an toàn.' WHERE id = 230;
UPDATE questions SET explanation = 'Ký hiệu hình cây xăng trên bảng đồng hồ báo hiệu xe sắp hết nhiên liệu.' WHERE id = 231;
UPDATE questions SET explanation = 'Xăng sinh học và khí sinh học là các loại nhiên liệu thân thiện môi trường, giảm thiểu ô nhiễm so với xăng và dầu diesel truyền thống.' WHERE id = 232;
UPDATE questions SET explanation = 'Biện pháp tiết kiệm nhiên liệu gồm: bảo dưỡng xe theo định kỳ và có kế hoạch lộ trình trước khi chạy; kiểm tra áp suất lốp theo quy định và chạy xe với tốc độ phù hợp với tình trạng mặt đường và mật độ giao thông. Do đó cả hai ý đều đúng.' WHERE id = 233;
UPDATE questions SET explanation = 'Khi mở cửa xuống xe, phải quan sát tình hình giao thông phía trước, phía sau và phía bên mở cửa, mở hé cánh cửa, nếu bảo đảm an toàn mới mở cửa ở mức cần thiết để xuống xe.' WHERE id = 234;
UPDATE questions SET explanation = 'Khi qua đường sắt không có rào chắn, không có người điều khiển giao thông, người lái xe phải giảm tốc độ, dừng lại trước vạch dừng, quan sát cả hai phía; nếu không có tàu đi tới thì tăng ga nhẹ vượt qua; nếu thấy có tàu đi tới thì dừng lại trước vạch dừng, chỉ khi tàu đi qua mới được đi. Do đó cả hai ý đều đúng.' WHERE id = 235;
UPDATE questions SET explanation = 'Thao tác "giảm tốc độ, dừng lại trước vạch dừng, quan sát cả hai phía, nếu không có tàu đi tới thì tăng ga nhẹ vượt qua; nếu có tàu đi tới thì dừng lại và chỉ khi tàu đi qua mới được đi" là đúng và bảo đảm an toàn khi qua đường sắt.' WHERE id = 236;
UPDATE questions SET explanation = 'Khi ô tô số tự động đi vào đường trơn trượt, lầy lội, người lái xe phải về số thấp, kết hợp phanh chân để giảm tốc độ, không về số N hay giữ nguyên số D tùy tiện.' WHERE id = 237;
UPDATE questions SET explanation = 'Khi động cơ đã khởi động muốn điều chỉnh ghế người lái, phải để cần số ở vị trí N, P hoặc số 0 để xe đứng yên an toàn, tránh xe tự lăn bánh.' WHERE id = 238;
UPDATE questions SET explanation = 'Khi điều khiển xe ô tô số tự động, người lái xe không sử dụng chân trái; chân phải điều khiển cả bàn đạp phanh và bàn đạp ga để tránh nhầm lẫn.' WHERE id = 239;
UPDATE questions SET explanation = 'Khi tầm nhìn bị hạn chế bởi sương mù hoặc mưa to, cần giảm tốc độ, chạy cách xa xe phía trước với khoảng cách an toàn, bật đèn sương mù và đèn chiếu gần.' WHERE id = 240;
UPDATE questions SET explanation = 'Khi bị đèn pha xe ngược chiều gây chói mắt, cần giảm tốc độ, giữ vững tay lái và nhìn chếch sang lề đường bên phải, không nhìn thẳng vào đèn.' WHERE id = 241;
UPDATE questions SET explanation = 'Để đạt hiệu quả phanh cao nhất, người lái xe mô tô phải giảm hết ga và sử dụng đồng thời cả phanh sau và phanh trước.' WHERE id = 242;
UPDATE questions SET explanation = 'Khi lái xe trên mặt đường nhiều "ổ gà", phải giảm tốc độ, về số thấp và giữ đều ga, không tăng tốc hay đánh lái liên tục.' WHERE id = 243;
UPDATE questions SET explanation = 'Khi gặp mưa to hoặc sương mù, cần bật đèn chiếu gần và đèn vàng (nếu có), điều khiển gạt nước, chạy chậm để quan sát được; nếu cần thì tìm chỗ an toàn dừng xe và bật đèn dừng khẩn cấp báo hiệu cho xe khác.' WHERE id = 244;
UPDATE questions SET explanation = 'Điều khiển xe trong trời mưa cần giảm tốc độ, tăng cường quan sát, không phanh gấp, không tăng ga hay đánh vô lăng đột ngột, bật đèn chiếu gần và mở gạt nước phù hợp để bảo đảm quan sát.' WHERE id = 245;
UPDATE questions SET explanation = 'Khi lùi xe phải quan sát bên trái, bên phải, phía sau xe, có tín hiệu cần thiết và lùi xe với tốc độ phù hợp.' WHERE id = 246;
UPDATE questions SET explanation = 'Điều khiển xe trong khu vực đông dân cư cần giảm tốc độ đến mức an toàn, quan sát, nhường đường cho người đi bộ, giữ khoảng cách an toàn với xe phía trước, đi đúng làn đường quy định và chỉ chuyển làn ở nơi cho phép. Do đó cả hai ý đều đúng.' WHERE id = 247;
UPDATE questions SET explanation = 'Khi nhập vào đường cao tốc, phải quan sát, phát tín hiệu, nhường đường cho các xe đang chạy trên đường cao tốc, khi đủ điều kiện an toàn thì tăng tốc độ cho xe nhập vào làn; nếu có làn tăng tốc thì phải cho xe chạy trên làn đó trước khi nhập vào làn của đường cao tốc.' WHERE id = 248;
UPDATE questions SET explanation = 'Khi ra khỏi đường cao tốc, phải quan sát tìm biển "lối ra", kiểm tra tình trạng giao thông phía sau và bên phải, nếu bảo đảm an toàn thì phát tín hiệu và chuyển dần sang làn bên phải; nếu có làn giảm tốc thì phải di chuyển trên làn đó trước khi ra khỏi đường cao tốc.' WHERE id = 249;
UPDATE questions SET explanation = 'Người lái xe chỉ được dừng, đỗ trên làn dừng khẩn cấp của đường cao tốc khi xe gặp sự cố, tai nạn hoặc trường hợp khẩn cấp không thể di chuyển bình thường.' WHERE id = 250;
UPDATE questions SET explanation = 'Trên đường đôi muốn vượt xe kéo rơ moóc, phải giữ khoảng cách an toàn, tránh điểm mù, bật xi nhan trái kết hợp đèn, còi xin vượt; khi xe kéo rơ moóc đã có tín hiệu cho vượt và đủ điều kiện an toàn thì vượt dứt khoát, không di chuyển song song; sau khi vượt phải quan sát gương chiếu hậu bên phải, chỉ trở về làn khi đủ khoảng trống an toàn. Do đó cả ba ý đều đúng.' WHERE id = 251;
UPDATE questions SET explanation = 'Khi ô tô số tự động xuống đường dốc dài, độ dốc cao, cần nhả bàn đạp ga, về số thấp và đạp phanh chân với mức độ phù hợp để giảm tốc độ.' WHERE id = 252;
UPDATE questions SET explanation = 'Khi đi từ đường nhánh ra đường chính, phải quan sát, giảm tốc độ, phát tín hiệu và nhường đường cho xe trên đường chính từ bất kỳ hướng nào tới.' WHERE id = 253;
UPDATE questions SET explanation = 'Khi có nhu cầu sử dụng điện thoại, người lái xe phải giảm tốc độ để dừng xe ở nơi cho phép rồi mới sử dụng điện thoại, tuyệt đối không dùng điện thoại khi đang lái xe.' WHERE id = 254;
UPDATE questions SET explanation = 'Thói quen chỉ sử dụng phanh trước khi điều khiển xe mô tô tay ga rất dễ gây tai nạn vì có thể làm khóa bánh trước và mất lái, đặc biệt ở tốc độ cao.' WHERE id = 255;
UPDATE questions SET explanation = 'Khi mở cửa xuống xe, phải quan sát phía trước, phía sau và bên phía mở cửa để phát hiện phương tiện đang di chuyển tới gần; khi đủ điều kiện an toàn mới mở hé cửa rồi mở ở mức cần thiết để xuống xe.' WHERE id = 256;
UPDATE questions SET explanation = 'Khi quay đầu xe mô tô, cần bật tín hiệu báo rẽ trước, từ từ giảm tốc độ đến mức có thể dừng lại, chỉ quay đầu ở nơi được phép, quan sát an toàn phía trước, phía sau, hai bên và nhường đường cho xe từ bên phải và phía trước đi tới. Do đó cả ba ý đều đúng.' WHERE id = 257;
UPDATE questions SET explanation = 'Tay ga trên xe mô tô hai bánh dùng để điều khiển xe chạy về phía trước và điều tiết công suất động cơ qua đó điều khiển tốc độ của xe. Do đó đáp án là ý 1 và ý 2.' WHERE id = 258;
UPDATE questions SET explanation = 'Gương chiếu hậu của xe mô tô hai bánh dùng để quan sát an toàn phía sau của bên trái và bên phải trước khi chuyển hướng.' WHERE id = 259;
UPDATE questions SET explanation = 'Để bảo đảm an toàn, người lái xe mô tô hai bánh cần tăng ga từ từ và giảm ga thật nhanh, tránh tăng ga đột ngột gây mất kiểm soát.' WHERE id = 260;
UPDATE questions SET explanation = 'Tránh đổ ngã ở nơi đường xấu, nhỏ, hẹp cần: đi ở tốc độ thấp, quan sát liên tục khoảng cách 5-10 mét phía trước để điều chỉnh sớm hướng di chuyển; không dùng phanh trước để tránh khóa bánh dẫn hướng; không lắc người sang trái hoặc phải nhiều, giữ trọng tâm cơ thể trùng với trọng tâm của xe. Do đó cả ba ý đều đúng.' WHERE id = 261;
UPDATE questions SET explanation = 'Khi lái xe ô tô điện xuống dốc dài, đổ đèo, cần kiểm tra hệ thống an toàn, pin trước khi xuất phát; nhả chân ga để phanh tái sinh hoạt động; rà phanh chân để kịp thời xử lý tình huống khẩn cấp. Do đó cả ba ý đều đúng.' WHERE id = 262;
UPDATE questions SET explanation = 'Khi lái xe ô tô điện qua khu vực ngập nước, người lái xe phải tìm hiểu khả năng chịu ngập nước của xe để xác định cung đường di chuyển; giữ vững tay lái, đi đều ga, tránh để xe chết máy giữa dòng, không nên dừng xe trên đường ngập nước; lái xe tốc độ chậm, không tạo sóng và giữ khoảng cách an toàn với các phương tiện xung quanh, nhất là người đi bộ. Do đó cả ba ý đều đúng.' WHERE id = 263;
UPDATE questions SET explanation = 'Kiểm tra mức dầu bôi trơn động cơ đúng cách: rút que thăm dầu trên các-te, lau sạch, cắm lại vào các-te rồi rút ra quan sát vệt dầu trên que thăm; mức dầu phải nằm trong khoảng giữa vạch mức tối thiểu và tối đa được thể hiện trên que thăm.' WHERE id = 264;
UPDATE questions SET explanation = 'Xe ô tô tham gia giao thông phải có kính chắn gió, kính cửa là kính an toàn bảo đảm tầm nhìn; đủ hệ thống hãm và chuyển hướng có hiệu lực, tay lái ở bên trái, còi đúng quy chuẩn; có đủ đèn chiếu sáng gần và xa, đèn soi biển số, đèn báo hãm, đèn tín hiệu; có đủ bộ phận giảm thanh, giảm khói, kết cấu đủ độ bền và ổn định. Do đó cả hai ý đều đúng.' WHERE id = 265;
UPDATE questions SET explanation = 'Xe mô tô và xe ô tô tham gia giao thông trên đường bộ bắt buộc phải có đủ bộ phận giảm thanh để hạn chế tiếng ồn gây ảnh hưởng đến môi trường và cộng đồng.' WHERE id = 266;
UPDATE questions SET explanation = 'Xe ô tô phải có đủ đèn chiếu sáng gần và xa, đèn soi biển số, đèn báo hãm và đèn tín hiệu. Dàn đèn pha trên nóc xe không phải là trang bị bắt buộc theo quy định an toàn kỹ thuật.' WHERE id = 267;
UPDATE questions SET explanation = 'Kính chắn gió của xe ô tô phải là loại kính an toàn, kính nhiều lớp, đúng quy cách, không rạn nứt, bảo đảm hình ảnh quan sát rõ ràng, không bị méo mó.' WHERE id = 268;
UPDATE questions SET explanation = 'Bánh xe phải có kết cấu chắc chắn, lắp đặt đúng quy cách; lốp phải đủ số lượng, đủ áp suất, không phồng rộp, đúng cỡ lốp, và lốp trên cùng một trục trong điều kiện hoạt động bình thường phải cùng kiểu loại. Do đó cả hai ý đều đúng.' WHERE id = 269;
UPDATE questions SET explanation = 'Hệ thống lái phải bảo đảm cho xe chuyển hướng chính xác, điều khiển nhẹ nhàng, an toàn ở mọi vận tốc và tải trọng trong phạm vi tính năng kỹ thuật cho phép; khi hoạt động các cơ cấu không được va chạm với bộ phận khác, lực tác động lên vành tay lái khi quay trái và phải không có sự khác biệt đáng kể. Do đó cả hai ý đều đúng.' WHERE id = 270;
UPDATE questions SET explanation = 'Bảo dưỡng thường xuyên giúp xe luôn có tính năng kỹ thuật tốt, giảm hao mòn chi tiết, kéo dài tuổi thọ; đồng thời ngăn ngừa, phát hiện kịp thời hư hỏng và sai lệch kỹ thuật để khắc phục và giữ gìn hình thức bên ngoài. Do đó cả hai ý đều đúng.' WHERE id = 271;
UPDATE questions SET explanation = 'Động cơ diesel không nổ có thể do: hết nhiên liệu, lõi lọc nhiên liệu bị tắc, lọc khí bị tắc, nhiên liệu lẫn không khí và tạp chất. Động cơ diesel không dùng bugi (không có tia lửa điện), nên đáp án A đúng.' WHERE id = 272;
UPDATE questions SET explanation = 'Ống xả không được đặt ở vị trí gây cháy xe hoặc ảnh hưởng đến người ngồi trên xe, không gây cản trở hoạt động của hệ thống khác; miệng thoát khí thải không được hướng về phía trước và không được hướng về bên phải theo chiều tiến của xe. Do đó cả hai ý đều đúng.' WHERE id = 273;
UPDATE questions SET explanation = 'Dây đai an toàn phải đủ số lượng, lắp đặt chắc chắn, không rách đứt, khóa cài đóng mở nhẹ nhàng không tự mở, không bị kẹt; kéo ra thu vào dễ dàng, cơ cấu hãm giữ chặt dây khi giật đột ngột.' WHERE id = 274;
UPDATE questions SET explanation = 'Động cơ 4 kỳ là loại động cơ để hoàn thành một chu trình công tác, pít tông thực hiện 4 hành trình, trong đó có một lần sinh công.' WHERE id = 275;
UPDATE questions SET explanation = 'Hệ thống bôi trơn cung cấp dầu bôi trơn đủ và sạch dưới áp suất nhất định để bôi trơn các chi tiết động cơ, nhằm giảm ma sát, giảm mài mòn, làm kín, làm sạch, làm mát và chống gỉ.' WHERE id = 276;
UPDATE questions SET explanation = 'Niên hạn sử dụng của xe ô tô tải (tính từ năm sản xuất) không quá 25 năm.' WHERE id = 277;
