UPDATE questions SET explanation = 'Công dụng của động cơ xe ô tô: khi làm việc, nhiệt năng được biến đổi thành cơ năng làm trục khuỷu quay, truyền lực đến các bánh xe chủ động tạo ra chuyển động tịnh tiến cho xe.' WHERE id = 279;
