UPDATE questions SET explanation = 'Hộp số dùng để truyền và thay đổi mô men từ động cơ đến bánh xe chủ động, cắt truyền động từ động cơ đến bánh xe chủ động và bảo đảm cho xe ô tô chuyển động lùi.' WHERE id = 282;
UPDATE questions SET explanation = 'Hệ thống lái dùng để thay đổi hướng chuyển động hoặc giữ cho xe ô tô chuyển động ổn định theo hướng xác định.' WHERE id = 283;
UPDATE questions SET explanation = 'Hệ thống phanh dùng để giảm tốc độ, dừng chuyển động của xe ô tô và giữ cho xe ô tô đứng yên trên dốc.' WHERE id = 284;
